/* =====================================================================
   NAME HASHER — FNV-1a + xorshift128 PRNG
   ===================================================================== */
const NameHasher = {
  // FNV-1a over Unicode codepoints → 32-bit seed
  hash(name) {
    let h = 2166136261;
    for (const cp of name) {
      const c = cp.codePointAt(0);
      h ^= c;
      h = Math.imul(h, 16777619);
      h >>>= 0;
    }
    return h >>> 0;
  },

  // splitmix32 to expand seed into 4×32-bit xorshift128 state
  seededRNG(seed) {
    let s = seed >>> 0;
    function sm() {
      s = (s + 0x9e3779b9) >>> 0;
      let z = s;
      z = Math.imul(z ^ (z >>> 16), 0x85ebca6b) >>> 0;
      z = Math.imul(z ^ (z >>> 13), 0xc2b2ae35) >>> 0;
      return (z ^ (z >>> 16)) >>> 0;
    }
    let [a,b,c,d] = [sm(),sm(),sm(),sm()];
    return function next() {
      let t = (b << 9) >>> 0;
      let r = Math.imul(a, 0x9e3779bb) >>> 0;
      r = ((r >>> 11) ^ r) >>> 0;
      c ^= a; d ^= b; b = ((b << 9)|(b >>> 23)) >>> 0; b ^= c;
      a ^= d; c = ((c << 11)|(c >>> 21)) >>> 0; d = (d + 0x9e3779b9) >>> 0;
      [a,b,c,d] = [b>>>0, c>>>0, d>>>0, (a^t^r)>>>0];
      return (a >>> 0) / 4294967296;
    };
  },

  // Roll 4d6 drop lowest, range 3–18, D&D standard
  roll4d6(rng) {
    const dice = [1,2,3,4].map(() => Math.floor(rng()*6)+1);
    return dice.reduce((a,b)=>a+b,0) - Math.min(...dice);
  },

  rollD(rng, sides) { return Math.floor(rng()*sides)+1; },

  // Generate 6 stats with total normalized to 65–82
  genStats(rng) {
    let stats = [0,0,0,0,0,0].map(()=>this.roll4d6(rng));
    let total = stats.reduce((a,b)=>a+b,0);
    // Nudge toward 65–82 range
    while (total < 65) {
      const i = stats.indexOf(Math.min(...stats));
      stats[i] = Math.min(18, stats[i]+1); total++;
    }
    while (total > 82) {
      const i = stats.indexOf(Math.max(...stats));
      stats[i] = Math.max(8, stats[i]-1); total--;
    }
    return stats; // [str,dex,con,int,wis,cha]
  }
};

