function createBossCharacter(bossData) {
  const c = Object.create(Character.prototype);
  c.name = currentLang==='zh' ? bossData.name.zh : bossData.name.en;
  c._isBoss = true;
  c._bossIcon = bossData.icon;
  c.str=bossData.str; c.dex=bossData.dex; c.con=bossData.con;
  c.int=bossData.int; c.wis=bossData.wis; c.cha=bossData.cha;
  c.strMod=mod(c.str); c.dexMod=mod(c.dex); c.conMod=mod(c.con);
  c.intMod=mod(c.int); c.wisMod=mod(c.wis); c.chaMod=mod(c.cha);
  c.classKey   = bossData.classKey;
  c.classDef   = CLASSES[c.classKey];
  c.className  = c.classDef.name;
  c.level      = bossData.level + 3;
  c.proficiencyBonus = 3 + bossData.level;
  c.attackBonus = c.proficiencyBonus + c[bossData.attackStat+'Mod'];
  c.spellSaveDC = bossData.isCaster ? 8 + c.proficiencyBonus + c[(bossData.saveDCStat||'int')+'Mod'] : 0;
  let ac = bossData.acBase;
  if (bossData.acUseDex) ac += Math.min(c.dexMod, bossData.acDexCap ?? 99);
  if (bossData.acUseCon) ac += c.conMod;
  c.ac = ac;
  const avgDie = Math.floor((bossData.hitDie||10)/2)+1;
  c.maxHP = (avgDie + 3) * c.level + c.conMod * c.level;
  c.damageDie   = bossData.damageDie;
  c.damageBonus = c[bossData.attackStat+'Mod'] + bossData.level;
  c.initiative  = c.dexMod;
  c.subclassKey  = 'boss';
  c.subclassName = {zh:bossData.icon+' Boss',en:bossData.icon+' Boss'};
  c.subclassFlavor= {zh:'',en:''};
  c.title = '';
  c.skills = (bossData.customSkills||[]).map(sk=>Object.assign({},sk,{_usesLeft:sk.uses===Infinity?Infinity:sk.uses}));
  c.resetCombat();
  for (const sk of c.skills) { if(sk.trigger==='passive'&&sk.onInit) sk.onInit(c); }
  if (bossData.beams) c.classDef = Object.assign({},c.classDef,{beams:bossData.beams});
  return c;
}

/* =====================================================================
   CHARACTER — builds a full D&D character from a name
   ===================================================================== */
class Character {
  constructor(name) {
    this.name = name.trim() || '???';
    const seed = NameHasher.hash(this.name);
    const rng  = NameHasher.seededRNG(seed);

    // 1. Generate ability scores [str,dex,con,int,wis,cha]
    const raw = NameHasher.genStats(rng);
    [this.str,this.dex,this.con,this.int,this.wis,this.cha] = raw;

    // 2. Modifiers
    this.strMod=mod(this.str); this.dexMod=mod(this.dex); this.conMod=mod(this.con);
    this.intMod=mod(this.int); this.wisMod=mod(this.wis); this.chaMod=mod(this.cha);

    // 3. Assign class
    this.classKey = assignClass(raw, rng);
    this.classDef  = CLASSES[this.classKey];
    this.className = this.classDef.name;

    // 4. Core stats
    this.level = 5;
    this.proficiencyBonus = 3; // level 5
    const primaryMod = this[this.classDef.attackStat+'Mod'];
    this.attackBonus  = this.proficiencyBonus + primaryMod;
    this.spellSaveDC  = this.classDef.isCaster
      ? 8 + this.proficiencyBonus + this[this.classDef.saveDCStat+'Mod']
      : 0;

    // AC
    let ac = this.classDef.acBase;
    if (this.classDef.acUseDex)  ac += Math.min(this.dexMod, this.classDef.acDexCap ?? 99);
    if (this.classDef.acUseCon)  ac += this.conMod;
    if (this.classDef.acUseWis)  ac += this.wisMod;
    this.ac = Math.max(10, ac);

    // HP: average hit die * level + CON*level
    const avgDie = Math.floor(this.classDef.hitDie / 2) + 1;
    this.maxHP = avgDie * this.level + this.conMod * this.level;
    this.maxHP = Math.max(10, this.maxHP);

    // Damage die
    this.damageDie = this.classDef.damageDie;
    this.damageBonus = this[this.classDef.attackStat+'Mod'];

    // Initiative
    this.initiative = this.dexMod;

    // 5. Skills — deep copy to allow per-instance uses tracking
    this.skills = deepCopySkills(this.classDef.skills);

    // 6. Title
    const adjList  = this.classDef.titleAdj[currentLang]||this.classDef.titleAdj.en;
    const nounList = this.classDef.titleNoun[currentLang]||this.classDef.titleNoun.en;
    const ti = Math.floor(rng()*adjList.length);
    const tn = Math.floor(rng()*nounList.length);
    this.title = currentLang==='zh'
      ? `"${adjList[ti]}${nounList[tn]}"`
      : `"The ${adjList[ti]} ${nounList[tn]}"`;

    // 7b. Assign subclass (next rng value after title)
    const subList = SUBCLASSES[this.classKey];
    const subIdx  = Math.floor(rng() * subList.length);
    const sub     = subList[subIdx];
    this.subclassKey    = sub.key;
    this.subclassName   = sub.name;
    this.subclassFlavor = sub.flavor;
    // Deep copy and inject subclass skill
    const subSkill = Object.assign({}, sub.skill, {
      _usesLeft: sub.skill.uses === Infinity ? Infinity : sub.skill.uses
    });
    this.skills.push(subSkill);

    // 8. Alignment (derived from name hash — two independent axes)
    this.goodness   = Math.floor(rng() * 9); // 0=极恶 … 8=极善
    this.lawfulness = Math.floor(rng() * 9); // 0=极混乱 … 8=极守序
    const gTier = this.goodness   >= 6 ? 'Good'    : this.goodness   >= 3 ? 'Neutral' : 'Evil';
    const lTier = this.lawfulness >= 6 ? 'Lawful'  : this.lawfulness >= 3 ? 'Neutral' : 'Chaotic';
    const gCode = this.goodness   >= 6 ? 'G'       : this.goodness   >= 3 ? 'N'       : 'E';
    const lCode = this.lawfulness >= 6 ? 'L'       : this.lawfulness >= 3 ? 'N'       : 'C';
    this.alignmentShort = (lCode === 'N' && gCode === 'N') ? 'TN' : lCode + gCode;
    this.alignment = (lTier === 'Neutral' && gTier === 'Neutral') ? 'True Neutral' : `${lTier} ${gTier}`;
    this.alignmentZh = {
      LG:'守序善良',NG:'中立善良',CG:'混乱善良',
      LN:'守序中立',TN:'绝对中立',CN:'混乱中立',
      LE:'守序邪恶',NE:'中立邪恶',CE:'混乱邪恶'
    }[this.alignmentShort] || this.alignment;

    // 9. Combat state (reset before each fight)
    this.resetCombat();

    // 8. Apply passive onInit effects
    for (const sk of this.skills) {
      if (sk.trigger==='passive' && sk.onInit) sk.onInit(this);
    }
    // Special per-class init
    if (this.classKey==='paladin')  this._smiteUses=4;
    if (this.classKey==='wizard')   { this._shieldCharges=2; this._fireball_used=false; }
    if (this.classKey==='monk')     this._ki=5;
    if (this.classKey==='warlock')  this._agathysDone=false;
    if (this.classKey==='bard')     this._cwCharges=3;
    if (this.classKey==='sorcerer') { this._twinReady=true; this._twinUsed=false; }
  }

  resetCombat() {
    this.currentHP = this.maxHP;
    this.tempHP    = 0;
    this.conditions = new Map();
    this.saveBonus  = 0;
    this._sneakUsed = false;
    this._dodgeUsed = false;
    this._colossusUsed = false;
    this._shieldUsed  = false;
    this._shieldActive = false;
    this.round = 0;
    this.aggressors = new Set(); // names of chars who have damaged this char
    this.healers    = new Set(); // names of chars who have healed this char
  }

  startOfTurn() {
    this._sneakUsed    = false;
    this._dodgeUsed    = false;
    this._colossusUsed = false;
    this._shieldUsed   = false;
    this._bbUsed       = false;   // Booming Blade resets each turn
    this._hordeUsed    = false;   // Horde Breaker resets each turn
    if (this._shieldActive) { this.ac -= 5; this._shieldActive = false; }
    // Tick down conditions
    for (const [k,v] of this.conditions) {
      if (v && typeof v.rounds === 'number') {
        v.rounds--;
        if (v.rounds <= 0) this.conditions.delete(k);
      }
    }
  }

  get isAlive() { return this.currentHP > 0; }
  get hpPct()   { return this.currentHP / this.maxHP; }
}

function mod(score) { return Math.floor((score - 10) / 2); }

function deepCopySkills(skills) {
  return skills.map(sk => Object.assign({}, sk, {
    _usesLeft: sk.uses === Infinity ? Infinity : sk.uses
  }));
}

function assignClass(raw, rng) {
  const [str,dex,con,int_,wis,cha] = raw;
  const top = Math.max(...raw);
  // Determine primary stat
  if (str === top) {
    const second = [dex,con,int_,wis,cha].reduce((a,b)=>a>b?a:b);
    if (cha >= second - 1) return 'paladin';
    if (con >= second - 1 && str >= 14) return 'barbarian';
    return 'fighter';
  }
  if (dex === top) {
    if (wis >= dex - 2 && wis >= 13) return rng() < 0.5 ? 'monk' : 'ranger';
    return 'rogue';
  }
  if (con === top) return 'fighter';
  if (int_ === top) return 'wizard';
  if (wis === top) {
    if (str >= wis - 2 || con >= wis - 2) return 'cleric';
    return rng() < 0.5 ? 'cleric' : 'druid';
  }
  if (cha === top) {
    if (int_ >= cha - 2) return 'warlock';
    if (wis >= cha - 2) return 'bard';
    return rng() < 0.5 ? 'sorcerer' : 'bard';
  }
  return 'fighter'; // fallback
}

/* =====================================================================
   COMBAT ENGINE — D&D simplified combat resolution
   ===================================================================== */
class CombatEngine {
  constructor(char1, char2) {
    this.char1 = char1;
    this.char2 = char2;
    const seed = NameHasher.hash(char1.name + '|vs|' + char2.name);
    this.rng   = NameHasher.seededRNG(seed);
    this.events = []; // full combat log
    this.round  = 0;
    this.extraAttackThisTurn = false;
  }

  rollD(count, sides) {
    let t = 0;
    for (let i = 0; i < count; i++) t += Math.floor(this.rng() * sides) + 1;
    return t;
  }

  rollD20(advantage=false, disadvantage=false) {
    const r1 = Math.floor(this.rng() * 20) + 1;
    if (!advantage && !disadvantage) return r1;
    const r2 = Math.floor(this.rng() * 20) + 1;
    return advantage ? Math.max(r1,r2) : Math.min(r1,r2);
  }

  log(event) {
    // Snapshot HP+tempHP at log time so BattleRenderer can animate bars step-by-step
    // (characters are already at final HP by the time replay starts)
    event._hp = {};
    if (this.char1) event._hp[this.char1.name] = { hp: this.char1.currentHP, tmp: this.char1.tempHP || 0 };
    if (this.char2 && this.char2 !== this.char1) event._hp[this.char2.name] = { hp: this.char2.currentHP, tmp: this.char2.tempHP || 0 };
    this.events.push(event);
  }

  // Resolve a full attack roll
  attackRoll(attacker, defender) {
    const hasAdv  = attacker.conditions.has('raging') || attacker.classKey==='barbarian'
                 || attacker._vengeanceVow || attacker.conditions.has('shadow_adv');
    const hasDisadv = defender.conditions.has('dodging');
    const advantage    = hasAdv && !hasDisadv;
    const disadvantage = hasDisadv && !hasAdv;
    const isMocked = attacker.conditions.has('mocked');

    const rawRoll = this.rollD20(advantage && !isMocked, disadvantage || isMocked);
    const total   = rawRoll + attacker.attackBonus;
    const critThreshold = attacker._critThreshold || 20;
    const crit    = rawRoll >= critThreshold;
    const actualCrit = crit || (attacker._assassinRound && this.round === 1);
    const fumble  = rawRoll === 1;
    const targetAC = defender.ac;

    const preHit = !fumble && (actualCrit || total >= targetAC);
    // Shield reaction
    if (!preHit && !fumble) {
      const shSk = defender.skills.find(s=>s.id==='shield_spell');
      if (shSk && shSk.onAttacked && shSk._usesLeft > 0) {
        shSk.onAttacked(defender, this);
        shSk._usesLeft--;
      }
    }
    // Cutting Words
    const cwSk = defender.skills.find(s=>s.id==='cutting_words');
    let cwMod = 0;
    if (cwSk && cwSk.onAttacked && cwSk._usesLeft > 0) {
      cwMod = cwSk.onAttacked(defender, this, total);
      if (cwMod < 0) cwSk._usesLeft--;
    }

    return { roll:rawRoll, total:total+cwMod, crit:actualCrit, fumble, hit: !fumble && (actualCrit || (total+cwMod)>=targetAC), advantage, disadvantage };
  }

  // Spell attack roll (uses spellAttack bonus = proficiency + casting stat)
  spellAttackRoll(attacker, defender) {
    const spellBonus = attacker.proficiencyBonus + (attacker[attacker.classDef.attackStat+'Mod'] || 0);
    const rawRoll = this.rollD20();
    const total   = rawRoll + spellBonus;
    const crit    = rawRoll === 20;
    const hit     = crit || total >= defender.ac;
    return { roll:rawRoll, total, crit, hit };
  }

  // Saving throw
  savingThrow(creature, ability, dc) {
    const statMod = creature[ability+'Mod'] || 0;
    const bonus   = statMod + (creature.saveBonus||0);
    const raw     = this.rollD20();
    // Check for advantage from skills
    let advSave = false;
    for (const sk of creature.skills) {
      if (sk.trigger==='passive' && sk.onSave) {
        const r = sk.onSave(creature, ability);
        if (r && r.advantage) { advSave=true; break; }
      }
    }
    const roll = advSave ? Math.max(raw, this.rollD20()) : raw;
    return (roll + bonus) >= dc;
  }

  // Damage roll for a standard attack
  damageRoll(attacker, defender, crit=false, dmgType='slashing') {
    let dice = crit ? this.rollD(2, attacker.damageDie) : this.rollD(1, attacker.damageDie);
    let bonus = attacker.damageBonus;

    // Rage damage bonus
    if (attacker.conditions.has('raging')) {
      bonus += attacker.conditions.get('raging').damageBonus || 0;
    }

    // Hunter's Mark bonus die
    if (attacker.conditions.has('hunters_mark')) {
      const hm = attacker.conditions.get('hunters_mark');
      dice += this.rollD(...hm.bonusDie);
    }

    // Hex bonus die
    if (attacker.conditions.has('hex_active')) {
      const hx = attacker.conditions.get('hex_active');
      dice += this.rollD(...hx.bonusDie);
    }

    // onHit passive skills (Sneak Attack, Divine Smite, Colossus Slayer, etc.)
    for (const sk of attacker.skills) {
      if (sk.trigger==='passive' && sk.onHit) {
        const extra = sk.onHit(attacker, defender, this);
        if (extra) dice += extra;
      }
    }

    let total = Math.max(1, dice + bonus);

    // Resistance (Barbarian Rage)
    if (attacker.conditions.has('raging') && ['slashing','piercing','bludgeoning'].includes(dmgType)) {
      // attacker rages — no resistance to self damage
    }
    if (defender.conditions.has('raging')) {
      const rageData = defender.conditions.get('raging');
      if (rageData.resist && rageData.resist.includes(dmgType)) total = Math.floor(total / 2);
    }

    return total;
  }

  // Apply damage to a creature (handles tempHP, Uncanny Dodge)
  applyDamage(target, amount, source) {
    // Track aggressor for alignment-based behavior
    if (source && source.name && target.aggressors) target.aggressors.add(source.name);
    // Uncanny Dodge
    const ud = target.skills.find(s=>s.id==='uncanny_dodge');
    if (ud && ud.onDamaged && ud._usesLeft > 0) {
      amount = ud.onDamaged(target, amount);
      ud._usesLeft--;
    }
    // Agathys reflect
    if (target.conditions.has('agathys') && source) {
      // close-range attack → reflect
      const ag = target.conditions.get('agathys');
      // (reflection logged separately in renderer)
    }
    // Totem Bear: resistance to all damage types while raging
    if (target.conditions.has('raging') && target._totemActive) amount = Math.floor(amount / 2);
    // Aura of Warding: spell resistance (source is a caster)
    if (target._spellResistance && source && source.classDef && source.classDef.isCaster) amount = Math.floor(amount / 2);
    // Temp HP absorbs first
    if (target.tempHP > 0) {
      const absorbed = Math.min(target.tempHP, amount);
      target.tempHP -= absorbed;
      amount -= absorbed;
    }
    target.currentHP = Math.max(0, target.currentHP - amount);
  }

  // Warlock Eldritch Blast — 2 beams
  eldritchBlast(attacker, defender) {
    let total = 0;
    for (let b = 0; b < 2; b++) {
      const roll = this.spellAttackRoll(attacker, defender);
      if (roll.hit) {
        const dmg = this.rollD(1,10) + attacker.chaMod;
        total += dmg;
        if (attacker.conditions.has('hex_active')) total += this.rollD(1,6);
        this.log({type:'beam',actor:attacker.name,target:defender.name,data:{beam:b+1,roll:roll.total,hit:true,dmg,crit:roll.crit,dmgType:'force'}});
        this.applyDamage(defender, dmg, attacker);
      } else {
        this.log({type:'beam',actor:attacker.name,target:defender.name,data:{beam:b+1,roll:roll.total,hit:false}});
      }
    }
    return total;
  }

  // Standard attack sequence (1 or 2 attacks)
  doAttacks(attacker, defender) {
    // Gloom Stalker: bonus attack on round 1 with +1d8
    if (attacker._gloomRound1 && this.round === 1) {
      attacker._gloomRound1 = false;
      if (defender.isAlive) {
        const gr = this.attackRoll(attacker, defender);
        if (gr.hit) {
          const gd = this.damageRoll(attacker, defender, gr.crit, 'piercing') + this.rollD(1,8);
          this.log({type:'attack',actor:attacker.name,target:defender.name,
            data:{roll:gr.roll,total:gr.total,ac:defender.ac,hit:true,crit:gr.crit,dmg:gd,dmgType:'piercing',skill:'Dread Ambusher'}});
          this.applyDamage(defender, gd, attacker);
        } else {
          this.log({type:'attack',actor:attacker.name,target:defender.name,
            data:{roll:gr.roll,total:gr.total,ac:defender.ac,hit:false,skill:'Dread Ambusher'}});
        }
      }
    }
    const attacks = 1 + (attacker.classDef.extraAttacks||0) + (this.extraAttackThisTurn ? 1 : 0);
    this.extraAttackThisTurn = false;
    let totalDmg = 0;
    for (let a = 0; a < attacks; a++) {
      if (!defender.isAlive) break;
      const roll = this.attackRoll(attacker, defender);
      if (roll.hit) {
        const dmgType = attacker.classKey==='ranger' ? 'piercing' :
                        attacker.classKey==='monk'   ? 'bludgeoning' : 'slashing';
        const dmg = this.damageRoll(attacker, defender, roll.crit, dmgType);
        this.log({type:'attack',actor:attacker.name,target:defender.name,
          data:{roll:roll.roll,total:roll.total,ac:defender.ac,hit:true,crit:roll.crit,
                dmg,dmgType,advantage:roll.advantage}});
        this.applyDamage(defender, dmg, attacker);
        totalDmg += dmg;
      } else {
        this.log({type:'attack',actor:attacker.name,target:defender.name,
          data:{roll:roll.roll,total:roll.total,ac:defender.ac,hit:false,fumble:roll.fumble}});
      }
    }
    return totalDmg;
  }

  // Start-of-turn DoT effects (Spirit Guardians, Call Lightning)
  processStartOfTurn(active, target) {
    if (target.conditions.has('sg_active')) {
      const sg = target.conditions.get('sg_active');
      const dmg = this.rollD(...sg.dmgDice);
      const saved = this.savingThrow(active, sg.saveType, sg.dc);
      const final = saved ? Math.floor(dmg/2) : dmg;
      if (final > 0) this.applyDamage(active, final, target);
      this.log({type:'dot',actor:target.name,target:active.name,data:{effect:'Spirit Guardians',dmg:final,saved,dmgType:'radiant'}});
    }
    if (active.conditions.has('lightning_active')) {
      const cl = active.conditions.get('lightning_active');
      if (cl.turns > 0) {
        cl.turns--;
        const dmg = this.rollD(...cl.dmgDice);
        const saved = this.savingThrow(target, cl.saveType, cl.dc);
        const final = saved ? Math.floor(dmg/2) : dmg;
        if (final > 0) this.applyDamage(target, final, active);
        this.log({type:'dot',actor:active.name,target:target.name,data:{effect:'Call Lightning',dmg:final,saved,dmgType:'lightning'}});
      }
    }
    // Stun check
    if (active.conditions.has('stunned')) {
      this.log({type:'stun',actor:active.name,data:{effect:'Stunned — loses turn'}});
      return true; // skip turn
    }
    return false;
  }

  // AI: choose best action for this turn
  chooseAndAct(active, opponent) {
    active.round = this.round;
    const ctx = { self:active, target:opponent, round:this.round };

    // Alignment axes (default neutral if not set)
    const goodness   = active.goodness   ?? 4;
    const lawfulness = active.lawfulness ?? 4;
    const isChaotic  = lawfulness <= 2;
    const isGood     = goodness   >= 6;
    const targetAttackedUs = active.aggressors && active.aggressors.has(opponent.name);

    // --- Bonus action first (buffs, heals) ---
    for (const sk of active.skills) {
      if (sk.trigger!=='active' || sk.timing!=='bonus') continue;
      if (sk._usesLeft <= 0) continue;
      if (sk.condition && !sk.condition(ctx)) continue;
      sk._usesLeft = sk.uses===Infinity ? Infinity : sk._usesLeft-1;
      sk.effect(active, opponent, this);
    }

    // --- Main action ---
    // Good chars reluctant to attack non-aggressors: -3 to offensive priority
    const goodPenalty = (isGood && !targetAttackedUs) ? 3 : 0;
    const actionSkills = active.skills
      .filter(sk=>sk.trigger==='active' && sk.timing==='action' && sk._usesLeft>0 && (!sk.condition||sk.condition(ctx)))
      .map(sk => ({ sk, eff: (sk.priority||0) - goodPenalty }))
      .sort((a,b)=>b.eff-a.eff);

    if (actionSkills.length > 0) {
      let chosen;
      if (isChaotic && actionSkills.length > 1) {
        // Chaotic: weighted-random selection (deterministic via seeded combat RNG)
        const weights = actionSkills.map(s => Math.max(1, s.eff + 50));
        const total   = weights.reduce((a,b)=>a+b, 0);
        let r = this.rollD(1, total) - 1;
        chosen = actionSkills[0].sk;
        for (let i = 0; i < actionSkills.length; i++) {
          r -= weights[i];
          if (r < 0) { chosen = actionSkills[i].sk; break; }
        }
      } else {
        chosen = actionSkills[0].sk;
      }
      chosen._usesLeft = chosen.uses===Infinity ? Infinity : chosen._usesLeft-1;
      chosen.effect(active, opponent, this);
    } else {
      // Default: weapon attacks (or Eldritch Blast for warlock)
      if (active.classKey==='warlock') {
        this.eldritchBlast(active, opponent);
      } else {
        this.doAttacks(active, opponent);
      }
    }
  }

  // Run the full battle and return events array
  fight() {
    const { char1, char2 } = this;
    char1.resetCombat(); char2.resetCombat();
    // Re-apply passive onInits after reset
    for (const c of [char1, char2]) {
      for (const sk of c.skills) {
        if (sk.trigger==='passive' && sk.onInit) sk.onInit(c);
      }
      if (c.classKey==='paladin')  c._smiteUses=4;
      if (c.classKey==='wizard')   { c._shieldCharges=2; c._fireball_used=false; }
      if (c.classKey==='monk')     c._ki=5;
      if (c.classKey==='warlock')  c._agathysDone=false;
      if (c.classKey==='bard')     c._cwCharges=3;
      if (c.classKey==='sorcerer') { c._twinReady=true; c._twinUsed=false; }
    }
    this.events = [];
    this.round  = 0;

    // Initiative
    const init1 = this.rollD20() + char1.initiative;
    const init2 = this.rollD20() + char2.initiative;
    this.log({type:'initiative',data:{[char1.name]:init1,[char2.name]:init2}});
    const order = init1 >= init2 ? [char1,char2] : [char2,char1];

    // Combat loop — max 20 rounds
    for (this.round = 1; this.round <= 20; this.round++) {
      this.log({type:'round_start',data:{round:this.round}});
      for (const active of order) {
        const opponent = active === char1 ? char2 : char1;
        if (!active.isAlive || !opponent.isAlive) break;
        active.startOfTurn();
        const skipTurn = this.processStartOfTurn(active, opponent);
        if (!opponent.isAlive) break;
        if (!skipTurn) this.chooseAndAct(active, opponent);
        if (!opponent.isAlive) break;
      }
      if (!char1.isAlive || !char2.isAlive) break;
    }

    // Determine winner
    let winner, loser;
    if (!char1.isAlive && !char2.isAlive) {
      winner = char1.hpPct >= char2.hpPct ? char1 : char2;
      loser  = winner === char1 ? char2 : char1;
    } else if (!char2.isAlive) {
      winner = char1; loser = char2;
    } else if (!char1.isAlive) {
      winner = char2; loser = char1;
    } else {
      // Timeout
      winner = char1.hpPct >= char2.hpPct ? char1 : char2;
      loser  = winner === char1 ? char2 : char1;
      this.log({type:'timeout',data:{winner:winner.name}});
    }

    this.log({type:'victory',data:{winner:winner.name,loser:loser.name,rounds:this.round}});
    return { winner, loser, events:this.events, rounds:this.round };
  }
}

module.exports = { NameHasher, Character, CombatEngine, CLASSES, SUBCLASSES, mod };
